parse(): void {
  // Resolve the DDL export relative to the configured schema dir — this is a
  // static file, NOT a live DB; the agent never opens a database connection.
  const ddlPath = path.join(this.schemaDir, 'schema.sql');
  if (!fs.existsSync(ddlPath)) {
    // Fail fast with the exact path so a bad schemaDir is obvious, rather than
    // silently parsing an empty schema and generating queries against nothing.
    throw new Error(`Schema file not found: ${ddlPath}`);
  }

  const ddl = fs.readFileSync(ddlPath, 'utf-8');
  this.tables = this.parseDDL(ddl);       // regex/pattern-parse DDL -> table/column/FK map
  this.parseReferenceQueries();           // layer in the team's trusted example queries
}

buildSchemaContext(schemaFilter?: string): string {
  const tables = this.getTables(schemaFilter);   // optional filter -> one schema only (used by --list-tables)
  const parts: string[] = [];

  // Header + a plain-English gloss of each schema's role, so the model knows
  // Core = transactional and Reporting = star schema before it sees any tables.
  parts.push('## App Database Schema\n');
  parts.push('### Schemas');
  parts.push('- **Core** — Transactional tables (users, conversations, messages, workflows)');
  parts.push('- **Reporting** — Star schema (fact + dimension tables)\n');

  for (const [schema, schemaTables] of bySchema) {
    parts.push(`### ${schema} Schema (${schemaTables.length} tables)\n`);
    for (const t of schemaTables) {
      const cols = t.columns.map(c => {
        let desc = `  ${c.name} ${c.type}`;
        // Surface PK and NOT NULL as inline hints — they steer the model toward
        // valid join keys and null-safe filters without it guessing.
        if (c.isPrimaryKey) desc += ' PK';
        if (!c.nullable) desc += ' NOT NULL';
        return desc;
      }).join('\n');
      // Bracket-quoted [schema].[table] models the target dialect's quoting up front.
      parts.push(`[${schema}].[${t.table}]`);
      parts.push(cols);
    }
  }
  return parts.join('\n');
}

private buildSystemPrompt(dialect: string): string {
  const schemaContext = this.schemaParser.buildSchemaContext();          // the table/column digest
  const referenceQueries = this.schemaParser.buildReferenceQueryContext(); // house-style exemplars

  // dialect is interpolated into the persona line so one rule set retargets
  // MSSQL vs Postgres; the SELECT-only guarantee is enforced HERE at generation
  // time (rule 1), not by a downstream sanitizer.
  return `You are an expert SQL query generator for the app's database.
You generate production-ready ${dialect.toUpperCase()} queries.

## Rules
1. ONLY generate SELECT queries — never INSERT, UPDATE, DELETE, DROP, ALTER
2. Use the exact table and column names from the schema
3. Always use proper JOINs — never implicit joins
4. Include ORDER BY for meaningful result ordering
5. For the Reporting star schema, always join through dimension tables

${schemaContext}

${referenceQueries}`;   // schema first, then exemplars — exemplars read as style, not law
}

private parseLLMResponse(response: string): { query: string; explanation?: string; tablesUsed: string[] } {
  // Non-greedy [\s\S]*? stops at the FIRST closing fence so a trailing prose
  // block isn't swallowed into the query; no fence -> heuristic fallback.
  const sqlMatch = response.match(/```sql\s*([\s\S]*?)```/);
  const query = sqlMatch ? sqlMatch[1].trim() : this.extractFallbackQuery(response);

  // Prefer the model's declared TABLES_USED line; if it skipped it, derive the
  // list FROM the query itself so this is never empty. filter(Boolean) drops
  // empty entries left by a trailing comma.
  const tablesMatch = response.match(/TABLES_USED:\s*(.+)/);
  const tablesUsed = tablesMatch
    ? tablesMatch[1].split(',').map(t => t.trim()).filter(Boolean)
    : this.inferTablesFromQuery(query);

  // Greedy to end-of-string: capture the whole trailing note. Left undefined
  // (not '') when absent, so callers can tell 'omitted' from 'empty'.
  const explainMatch = response.match(/EXPLANATION:\s*([\s\S]*?)(?:$)/);
  const explanation = explainMatch ? explainMatch[1].trim() : undefined;

  return { query, explanation, tablesUsed };
}

async execute(message: AgentMessage): Promise<AgentResponse> {
  this.schemaParser.parse();   // re-parse every run — no cache, so a re-exported schema.sql is always current

  const systemPrompt = this.buildSystemPrompt(input.dialect);
  const userPrompt = this.buildUserPrompt(input.question, input.explain);

  const llmResult = await callClaudeSonnet(systemPrompt, userPrompt, {
    temperature: 0.1,   // near-deterministic: same question + schema -> stable, reviewable SQL
    maxTokens: 4096,    // bounds cost while leaving room for a large query + explanation
  });

  const parsed = this.parseLLMResponse(llmResult.answer);
  // ...

  if (input.save) {   // persistence is opt-in; a bare run only prints to the terminal
    fs.mkdirSync(this.outputDir, { recursive: true });   // idempotent — safe if the dir already exists
    const sqlPath = path.join(this.outputDir, `DbQuery_${ts}.sql`);
    // Prefix the runnable file with the originating question so the artifact self-documents.
    fs.writeFileSync(sqlPath, `-- Question: ${input.question}\n\n${parsed.query}\n`);
  }
  return this.success(result, 'Query generated successfully');
}
